import{mix,syncContext}from './world.js';import{changeArea}from './social.js';
import{ensureHuman,initPeopleWorld}from './people-world.js';
// Identification, discovery and foster durations are game assumptions, not legal deadlines.
export function initCustody(s){s.custody??={version:1,identification:{collar:false,chip:false,registered:false,ownerId:null,updatedDay:null,source:'game-assumption'},missingReport:null,intake:null,foster:null,nextFoster:s.day+180};return s.custody;}
export function returnKnownHome(s,log,remember){const t=s.story;if(!t.returnHome||!t.returnArea)return false;s.worldModel.history.push({day:s.day,area:s.areaId,context:s.worldModel.context.id});s.lastAreaChange={day:s.day,reason:'reunion'};s.home=t.returnHome;s.areaId=t.returnArea;s.encounterBase=t.returnEncounterBase||0;s.friend={...t.returnFriend};s.dogBond=s.friend.bond;s.worldModel.context={...t.returnContext};s.worldModel.contextArea=s.areaId;s.worldModel.resource=t.returnResource;s.worldModel.care=t.returnCare;s.caregiverId=t.returnCaregiver||s.custody?.identification.ownerId||s.caregiverId;t.lost=false;t.reunited=true;t.settleAt=s.day+3;s.stress=Math.max(0,s.stress-20);initPeopleWorld(s);remember(s,'reunion');log(s,'reunion','익숙한 사람이 문 앞에 나타났다. 목소리와 손을 확인한 뒤 곁으로 몸을 붙인다. 다시 돌아온 잠자리와 물그릇에서 익숙한 냄새가 난다.');return true;}
export function custodyStep(s,{log,remember}){const c=initCustody(s),e=initPeopleWorld(s),tag=(id,text,arc)=>{log(s,id,text);if(arc)s.log.at(-1).storyId=arc;};
const guardian=s.humans.find(h=>h.id===s.caregiverId);if(s.home==='family'&&!s.story.lost&&!['settling','review'].includes(c.foster?.stage)&&s.day>=90&&guardian){const identity=c.identification;if(!identity.collar&&guardian.care+guardian.knowledge>=95){identity.collar=true;identity.ownerId=guardian.id;identity.updatedDay=s.day;tag('identity-tag','사람이 내 목에 가벼운 목걸이를 맞춘다. 작은 표식이 달려 있고, 몸을 움직일 때 낯선 감촉이 스친다.');}if(!identity.chip&&s.day>=120&&e.visit&&guardian.knowledge>=45&&guardian.money>=35){identity.chip=true;identity.registered=true;identity.ownerId=guardian.id;identity.updatedDay=s.day;tag('identity-record','진료를 마친 사람이 내 몸의 식별 정보와 연락처를 확인한다. 작은 처치 뒤에는 잠깐 몸을 쉬게 하고 집으로 돌아온다.');}if(identity.ownerId&&identity.ownerId!==guardian.id){identity.ownerId=guardian.id;identity.updatedDay=s.day;tag('identity-updated','함께 사는 사람이 진료 기록과 연락처를 다시 확인한다. 새로운 생활의 정보가 내 기록에 함께 남는다.');}}
if(s.story.lost&&s.story.returnHome){const t=s.story,elapsed=s.day-t.lostAt;if(!c.missingReport&&elapsed>=1){const prior=s.humans.find(h=>h.id===t.returnCaregiver);c.missingReport={day:s.day,actor:t.returnCaregiver||c.identification.ownerId,active:!!prior&&prior.time>=30};if(c.missingReport.active)tag('owner-search','익숙한 사람과 떨어져 낯선 곳에 머문다. 한편 예전 보호자는 주변에 실종 사실을 알리고 찾는 움직임을 이어간다.','missing:'+t.lostAt);}
if(!c.intake&&s.home==='street'&&elapsed>=4&&elapsed<60&&mix(s.seed+s.day,1501)%1000<18){c.intake={id:'custody:'+s.day,start:s.day,next:s.day+2,stage:'checking',originArea:s.areaId};s.home='shelter';changeArea(s,'found-shelter');syncContext(s);s.caregiverId='intake-carer:'+s.areaId;ensureHuman(s,s.caregiverId,'shelter');initPeopleWorld(s);tag('found-intake','내 주변을 살피던 사람이 안전한 이동 공간을 가까이 둔다. 이동 뒤 보호시설의 조용한 자리에서 물과 담요를 받는다. 직원은 목걸이와 식별 정보를 확인하기 시작한다.',c.intake.id);remember(s,'found-shelter');}
const intake=c.intake;if(intake&&intake.stage==='checking'&&s.day>=intake.next){intake.stage='contact';intake.next=s.day+2;intake.identified=!!c.identification.ownerId&&(c.identification.collar||c.identification.chip&&c.identification.registered);tag('identity-check',intake.identified?'직원이 목걸이와 식별 기록에서 연락할 사람의 정보를 찾았다. 아직 낯선 잠자리에서 쉬는 동안 사람들 사이에 연락이 이어진다.':'직원이 식별 정보를 살폈지만 연락할 보호자를 바로 확인하지 못했다. 사진과 발견 장소를 기록하고 내 상태를 돌본다.',intake.id);}
if(intake&&intake.stage==='contact'&&s.day>=intake.next){if(intake.identified&&c.missingReport?.active){intake.stage='returned';intake.end=s.day;returnKnownHome(s,(s,id,text)=>tag(id,text,intake.id),remember);c.missingReport.active=false;return true;}intake.stage='waiting';intake.next=s.day+21;tag('owner-contact-wait','사진과 발견 장소를 바탕으로 보호자를 찾는 연락이 이어진다. 그동안은 같은 시설에서 먹고 쉬며 돌봄을 받는다.',intake.id);}
if(intake&&intake.stage==='waiting'&&s.day>=intake.next){intake.stage='unclaimed';intake.end=s.day;t.lost=false;t.longSeparated=true;t.returnHome=null;if(c.missingReport)c.missingReport.active=false;e.route='rescue-adoption';e.nextPlacement=s.day+7;tag('owner-unconfirmed','여러 차례 확인 뒤에도 예전 보호자와 연락이 닿지 않았다. 돌보는 사람은 계속 내 기록을 남기며 앞으로 지낼 공간을 알아보기 시작한다.',intake.id);remember(s,'unconfirmed-owner');}}
if(s.home==='shelter'&&!s.story.lost&&e.facility!=='petshop'&&!s.story.adoptionReview&&!s.medical.episode&&!s.clinical?.active&&!c.foster&&s.day>=c.nextFoster){c.nextFoster=s.day+240;const difficult=s.worldModel.care<50||s.day>=2920;if(difficult&&mix(s.seed+s.day,1502)%5===0){const fosterId='foster:'+s.areaId+':'+s.day,h=ensureHuman(s,fosterId,'guardian');h.name='임시로 돌보는 사람';if(h.money>=35&&h.time>=40){c.foster={id:fosterId,start:s.day,review:s.day+45,stage:'settling',previousArea:s.areaId};s.home='family';changeArea(s,'foster');syncContext(s);s.caregiverId=fosterId;s.familyBond=15;s.story.settleAt=s.day+12;initPeopleWorld(s);tag('foster-start','보호시설에서 만난 사람과 잠시 지낼 집으로 왔다. 그 사람은 직원과 먹이와 진료 기록을 나누고 조용한 잠자리부터 마련한다.',fosterId);remember(s,'foster-home');}}}
const f=c.foster;if(f&&['settling','review'].includes(f.stage)&&s.day>=f.review&&!s.medical.episode&&!s.clinical?.active){if(s.caregiverId!==f.id){f.stage='closed';f.end=s.day;return false;}const h=s.humans.find(h=>h.id===f.id);if(f.stage==='settling'){f.stage='review';f.review=s.day+14;tag('foster-review','함께 지내던 사람이 보호시설 직원과 내 생활과 앞으로의 돌봄을 이야기한다. 오늘도 같은 그릇과 잠자리에서 쉰다.',f.id);}else if(h&&h.time+h.care+h.money>=165){f.stage='adopted';f.end=s.day;s.adoptionRoute='foster-adoption';h.name='함께 사는 사람';h.decisions.push({day:s.day,kind:'foster-adopt'});tag('adopt','나를 임시로 돌보던 사람이 앞으로도 함께 지내기로 했다. 잠자리와 그릇은 그대로다. 익숙한 발소리가 매일 이어진다.',f.id);remember(s,'new-home');}else{f.stage='returned';f.end=s.day;s.home='shelter';changeArea(s,'foster-return');syncContext(s);s.caregiverId='foster-return:'+s.areaId;e.route='shelter-adoption';initPeopleWorld(s);tag('foster-return','임시로 돌보던 사람은 내 담요와 생활 기록을 직원에게 전했다. 보호시설로 돌아와 익숙한 물건을 곁에 두고 다시 쉬는 자리를 살핀다.',f.id);remember(s,'foster-return');}}
return false;}
export function validateCustody(s){const c=s.custody;if(!c)return;const i=c.identification;if(c.version!==1||!i||!['collar','chip','registered'].every(k=>typeof i[k]==='boolean')||!(i.ownerId===null||typeof i.ownerId==='string')||!Number.isFinite(c.nextFoster)||c.missingReport&&(typeof c.missingReport!=='object'||typeof c.missingReport.active!=='boolean'||!Number.isInteger(c.missingReport.day))||c.intake&&(!['checking','contact','waiting','returned','unclaimed'].includes(c.intake.stage)||!Number.isInteger(c.intake.next)||typeof c.intake.id!=='string'||!Number.isInteger(c.intake.start))||c.foster&&(!['settling','review','adopted','returned','closed'].includes(c.foster.stage)||typeof c.foster.id!=='string'||!Number.isInteger(c.foster.review)))throw Error('손상된 신원·보호 경과');}
